function enterMode(mode,replay=false,requested=null){if(!slots[mode])return;if(s)save();let v=null;if(mode==='career'){const target=replay?freeCareer(localStorage):(requested??preferredCareer(localStorage));v=readCareer(localStorage,target);if(requested&&!v)return;careerSlot=v?target:freeCareer(localStorage);if(!careerSlot){notice=T('저장 슬롯이 가득 찼습니다. 기존 커리어를 내보내고 삭제한 후 다시 시도하세요.','All slots are occupied. Export and delete an existing career first.');render();return}}else v=replay?null:readSlot(localStorage,mode);sessionMode=mode;resetView();if(!v&&mode==='career'){sessionMode='careerSetup';s=null;localStorage.setItem('apm-mode-v176','lobby');render();return}if(!v){v=newGame(mode==='tutorial'?'Tutorial':mode==='collection'?'Collection':'Challenge','CA','Independent',1960,'alternate');v.difficulty=mode==='tutorial'?'easy':preferredDifficulty} s=v;migrateCollection();if(mode==='tutorial'&&(!s.politics?.active||replay)){const q=CH.challenges.find(x=>x.year===1960);if(!q){notice=T('튜토리얼 데이터가 없습니다.','Tutorial data unavailable.');s=null;sessionMode='lobby';render();return}startRace(s,{name:q.opponent,historical:true},{tutorial:true,challenge:'tutorial-1960',year:1960,office:'prez',player:q.player,start:q.start,budget:q.budget,source:q.source})}tab=s.politics?.active&&!s.politics.active.finished?'warroom':mode==='tutorial'?'warroom':mode==='challenges'?'challenges':mode==='collection'?'people':'home';save();render();if(dataStatus==='seed')loadPeople()}
