function basePeople(){const old=W.seed.map(p=>({...p,terms:[{start:p.start+'-01-01',end:p.end+'-12-31',type:p.role,state:p.state,party:p.party,precision:'year'}],sample:true,wiki:({'C000121':'Joseph Gurney Cannon','H000953':'Hubert Humphrey','C000371':'Shirley Chisholm'}[p.id])}));return [...H.people,...(ER.people||[]),...old.filter(p=>!(ER.people||[]).some(x=>x.id===p.id))]}
people=basePeople();
function normalize(raw){return raw.filter(p=>p.id?.bioguide&&p.name&&Array.isArray(p.terms)).map(p=>({id:p.id.bioguide,name:p.name.official_full||[p.name.first,p.name.middle,p.name.last,p.name.suffix].filter(Boolean).join(' '),ko:W.seed.find(x=>x.id===p.id.bioguide)?.ko,terms:p.terms,birthday:p.bio?.birthday,deathday:p.bio?.deathday,gender:p.bio?.gender,ids:p.id,wiki:p.id.wikipedia,photo:imageBase+p.id.bioguide+'.jpg'}))}
async function loadPeople(){if(dataStatus==='loading')return;dataStatus='loading';if(tab==='people')render();try{const cache=await (window.caches?.open('apm-data-v1')||Promise.resolve(null));const get=async file=>{const url=historicalBase+file;let res;try{const local=await fetch('./data/'+file);if(local.ok&&local.headers.get('content-type')?.includes('json')){const records=await local.json();if(Array.isArray(records)&&records.length)return records}}catch{}try{res=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!res.ok)throw Error('HTTP '+res.status);try{if(cache)await cache.put(url,res.clone())}catch{}}catch(e){res=await cache?.match(url);if(!res)throw e}return res.json()};const results=await Promise.allSettled(['legislators-historical.json','legislators-current.json'].map(get));const raw=results.filter(r=>r.status==='fulfilled'&&Array.isArray(r.value)).flatMap(r=>r.value);const unique=new Map(normalize(raw).map(p=>[p.id,p]));people=[...unique.values(),...basePeople().filter(p=>p.historical||!unique.has(p.id)),...govPeople];dataStatus=results.every(r=>r.status==='fulfilled')?'ready':raw.length?'partial':'failed'}catch(e){dataStatus='failed'}if(['people','congress','quiz','states','home','warroom','relations','party','challenges'].includes(tab))refreshFromData()}
async function loadGovernors(){if(govStatus==='loading')return;govStatus='loading';render();try{const r=await fetchCached(governorCSV);govPeople=governorsFromCSV(await r.text(),W.states);if(!govPeople.length)throw Error('No valid records');people=[...people.filter(p=>!p.governor),...govPeople];govStatus='ready'}catch(e){govStatus='failed'}if(s)render()}
function termAt(p,y){return p.terms.find(t=>+t.start.slice(0,4)<=y&&+t.end.slice(0,4)>=y)}
function era(){return W.eras.find(e=>e.start<=s.year&&e.end>=s.year)||W.eras.at(-1)}
function activePeople(){return people.filter(p=>termAt(p,s?.year||1900))}
function personName(p){return esc(p.name)+(lang==='ko'&&p.ko?' <small>('+esc(p.ko)+')</small>':'')}
function photo(p,large=false,anonymous=false){const localId=localPortraits.has(p.id)?p.id:portraitRecords.find(x=>x.name===p.name)?.id;const local=localId?'./portraits/'+encodeURIComponent(localId)+'.jpg':null;return '<img class="portrait" loading="lazy" data-person="'+esc(p.id)+'" src="'+(local||safeUrl(p.photo||(!p.historical&&!p.presidential&&!p.governor?imageBase+p.id+'.jpg':null)).replace(/^#$/,fallback))+'" alt="'+(anonymous?'Portrait':esc(p.name))+'" onerror="this.onerror=null;this.dataset.photoMissing=1;this.src=\''+fallback+'\'">'}
function sourceLink(p){return p.historical?p.source:p.governor?p.source:p.presidential?p.terms[0].source:source(p.id)}
function personCard(p){const t=(filter!=='all'?p.terms.find(t=>t.type===filter&&(scope==='all'||(+t.start.slice(0,4)<=s.year&&+t.end.slice(0,4)>=s.year))):null)||termAt(p,s.year)||p.terms.at(-1);return '<article class="panel person">'+photo(p)+'<div class="details"><h3>'+personName(p)+'</h3><span class="tag">'+esc(tr(t.party||''))+'</span> <span class="tag">'+esc(t.type==='election'?T('대통령 선거 당선자','Presidential election winner'):tr(t.type))+'</span><p class="muted">'+esc(stateName(t.state||''))+' '+esc(t.start.slice(0,4))+'–'+esc(t.end.slice(0,4))+'</p><button data-person-open="'+esc(p.id)+'">'+T('프로필','Profile')+'</button></div></article>'}
const wikiCache=new Map();
async function wikiPortrait(p){if(!p.wiki)return null;if(wikiCache.has(p.id))return wikiCache.get(p.id);try{const a=await fetch('https://en.wikipedia.org/w/api.php?origin=*&action=query&format=json&redirects=1&prop=pageimages&piprop=thumbnail|name&pithumbsize=260&titles='+encodeURIComponent(p.wiki),{signal:AbortSignal.timeout(12000)}).then(r=>r.json());const page=Object.values(a.query.pages)[0];if(page.thumbnail?.source&&page.pageimage){const v={src:page.thumbnail.source,credit:'https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(page.pageimage)};wikiCache.set(p.id,v);return v}}catch{}return null}
function hydratePhotos(){for(const el of document.querySelectorAll('img[data-person]')){const p=people.find(x=>x.id===el.dataset.person)||(s?.encounters?.active?.person?.id===el.dataset.person?s.encounters.active.person:null);if(!p)continue;const setCredit=url=>{if(tab==='quiz'||(s?.encounters?.active?.fact==='name'&&s.encounters.active.selected===null&&s.encounters.active.person.id===p.id))return;el.title=L('사진 원본 및 출처','Original photo and credit');el.onclick=()=>window.open(url,'_blank','noopener');if(detail===p.id){const a=$('photocredit');if(a){a.href=url;a.hidden=false}}};let tried=false;const useWiki=async()=>{if(tried)return;tried=true;const v=await wikiPortrait(p);if(v&&el.isConnected){el.src=v.src;setCredit(v.credit)}};let alternate=false;const onfail=()=>{if(!p.historical&&!p.presidential&&!p.governor&&!alternate){alternate=true;el.src='https://raw.githubusercontent.com/unitedstates/images/gh-pages/congress/225x275/'+encodeURIComponent(p.id)+'.jpg';return}el.removeEventListener('error',onfail);el.src=fallback;useWiki()};el.onerror=null;el.addEventListener('error',onfail);const localRecord=portraitRecords.find(x=>x.id===p.id||x.name===p.name);if(localRecord)setCredit(localRecord.source||W.sources.photos);else if(!p.presidential&&!p.governor)setCredit(W.sources.photos);if((p.historical||p.presidential||p.governor)&&!localRecord)useWiki();else if(el.dataset.photoMissing==='1'||(el.complete&&el.naturalWidth===0))onfail()}}
function portraitGallery(){if(!portraitRecords.length)return '';const shown=portraitRecords.filter(x=>x.name).slice(0,18);return '<details class="panel" open><summary><strong>'+T('실제 의원 사진 자료','Bundled congressional portraits')+'</strong> · '+portraitRecords.length+'</summary><p class="muted">'+T('전체 시대 사진 갤러리 · 현재 게임 연도와 무관','All-era photo gallery · independent of current game year')+'</p><div class="portrait-gallery">'+shown.map(x=>'<a href="'+safeUrl(x.source)+'" target="_blank" rel="noopener"><img loading="lazy" src="./portraits/'+encodeURIComponent(x.id)+'.jpg" alt="'+esc(x.name)+'"><span>'+esc(x.name)+'</span></a>').join('')+'</div></details>'}
function heading(k,description=''){return '<div class="eyebrow">AMERICAN POLITICAL MANAGER · V17.8</div><h1>'+tr(k)+'</h1>'+(description?'<p class="muted">'+description+'</p>':'')}
