function stats(){return '<div class="stats">'+[[T('자금','Funds'),s.funds],[T('체력','Energy'),s.energy],[T('역량','Skill'),s.skill],[T('지지','Support'),s.support],[T('관계','Network'),s.network],[T('학습 점수','Knowledge'),s.points]].map(([a,b])=>'<div class="stat"><small>'+a+'</small><strong>'+b+'</strong></div>').join('')+'</div>'}
function showStart(){return button(T('시작 화면','Main menu'),'lobby:back')+'<div class="eyebrow">HISTORICAL CAREER SIMULATION</div><h1>American Political Manager</h1><p>'+T('1900년부터 미국 정치의 인물과 제도를 배우며 가상의 정치인을 육성하세요.','Learn U.S. political history while developing a fictional politician.')+'</p><div class="panel"><form id="startform"><label>'+T('정치인 이름','Fictional candidate')+'<input name="name" required maxlength="60" value="Alex Morgan"></label><label>'+T('시작 연도','Start year')+'<select name="year" id="startyear">'+Array.from({length:127},(_,i)=>1900+i).map(y=>'<option '+(y===1960?'selected':'')+'>'+y+'</option>').join('')+'</select></label><label>'+T('주','State')+'<select name="state" id="startstate"></select></label><label>'+T('정당','Party')+'<select name="party">'+['Democrat','Republican','Independent'].map(x=>'<option value="'+x+'">'+tr(x)+'</option>').join('')+'</select></label><label>'+T('게임 모드','Mode')+'<select name="mode" id="careermode">'+['staff','state51','alternate'].map(k=>'<option value="'+k+'">'+L(...modeLabel[k])+'</option>').join('')+'</select></label>'+guide.difficultySelect(preferredDifficulty,'startdifficulty')+'<p class="v18-mode-hint" id="v18-mode-hint"></p><button class="primary" type="submit">'+T('커리어 시작','Start career')+'</button></form></div>'}
function fillStates(){let previous=$('startstate').value,y=+$('startyear').value;$('startstate').innerHTML=W.states.filter(x=>x.admitted<=y).map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('');if(W.states.some(x=>x.id===previous&&x.admitted<=y))$('startstate').value=previous;else if(y>=1850)$('startstate').value='CA'}
function home(){const cw=careerSituation(s),e=era(),historical=W.events.filter(x=>x.year===s.year),p=activePeople()[Math.abs(s.year*4+s.quarter)%Math.max(1,activePeople().length)];return heading('home',T('현재 커리어','Your career'))+'<div class="panel career-header"><div class="eyebrow">'+s.year+' · Q'+s.quarter+' · '+T(e.ko,e.en)+'</div><h2>'+esc(s.name)+'</h2><p>'+esc(stateName(s.state))+' · '+tr(s.party)+' · '+tr(s.office)+' · '+s.age+' '+L('세','years old')+'</p></div>'+(s.mode==='historyMode'?'<p class="notice">'+L('구버전 가상 커리어 · 실제 역사 보존형 참모 모드와 다릅니다.','Legacy fictional career · not the protected historical staff mode.')+'</p>':'')+stats()+guide.careerGuide(s)+encounters.render('career')+'<section class="panel dynamic-brief"><div class="eyebrow">CAREER SITUATION</div><h2>'+T(...careerContexts[cw.context])+'</h2>'+(cw.report?'<p>'+L(cw.report.ko,cw.report.en)+'</p>':'<p>'+T('장기적인 조직 기반과 신뢰를 함께 쌓으세요.','Build organizational capacity and credibility over time.')+'</p>')+(cw.opportunities.length?'<p>'+T('다음 분기에 후속 기회가 예정되어 있습니다.','Follow-up opportunities are pending next quarter.')+'</p>':'')+'</section>'+(!v17.active()&&!career(s).retired?'<div class="panel" id="quarter-actions"><h2>'+T('분기 활동','Quarterly actions')+' · '+(s.actionsLeft??2)+'/2</h2><div class="toolbar">'+['study','organize','network','fundraise','rest'].map(x=>button(tr(x),'act:'+x,s.actionsLeft===0?'disabled':'')).join('')+'</div>'+button(T('세부 육성','Detailed development'),'open-development')+'</div>':'')+(historical.length?'<details class="panel v18-secondary"><summary>'+L('역사 브리핑','Historical briefing')+'</summary>'+historical.map(e=>'<p>'+T(e.ko,e.en)+' · <a target="_blank" rel="noopener" href="'+safeUrl(e.source)+'">'+T('자료','Source')+'</a></p>').join('')+'</details>':'')+(p?'<details class="panel v18-secondary"><summary>'+L('이 시대의 정치인','Meet a contemporary')+'</summary>'+personCard(p)+'</details>':'')+'<details class="panel"><summary>'+T('최근 활동 기록','Recent activity log')+'</summary>'+s.history.slice(0,6).map(x=>'<div class="log">'+x.year+' Q'+x.quarter+' · '+esc(tr(x.key))+' '+esc(x.args.map(tr).join(' / '))+'</div>').join('')+'</details>'}
function peoplePage(){const p=people.filter(x=>(scope==='all'||termAt(x,s.year))&&(filter==='all'||x.terms.some(t=>t.type===filter&&(scope==='all'||(+t.start.slice(0,4)<=s.year&&+t.end.slice(0,4)>=s.year))))&&(!query||[x.name,x.ko,x.id,...x.terms.map(t=>t.state)].join(' ').toLowerCase().includes(query.toLowerCase())));const pages=Math.max(1,Math.ceil(p.length/24));page=Math.min(page,pages-1);return heading('people',T('실제 인물 · 임기별 정당 및 지역','Real people · Party and state by term'))+portraitGallery()+'<div class="panel"><p>'+T('전체 데이터 상태','Dataset status')+': '+esc({seed:T('기본 기록','Starter records'),loading:T('불러오는 중','Loading'),ready:T('연방의원 데이터 연결됨','Congress dataset loaded'),failed:T('연결 실패 · 기본 기록 사용','Unavailable · using starter records')}[dataStatus])+' · '+people.length+' '+T('개 기록','records')+'</p>'+button(T('데이터 불러오기 / 재시도','Load / retry dataset'),'load',dataStatus==='loading'?'disabled':'')+' <a href="'+W.sources.congress+'" target="_blank" rel="noopener">'+T('데이터 출처','Data source')+'</a></div><div class="toolbar"><input id="search" placeholder="'+T('이름, 주, ID 검색','Name, state, ID')+'" value="'+esc(query)+'"><select id="scope"><option value="era">'+s.year+'</option><option value="all" '+(scope==='all'?'selected':'')+'>'+T('모든 시대','All eras')+'</option></select><select id="filter">'+[['all',T('전체','All')],['rep',tr('rep')],['sen',tr('sen')],['gov',tr('gov')],['prez',tr('prez')],['vp',tr('vp')],['chief',tr('chief')],['justice',tr('justice')],['candidate',tr('candidate')],['activist',tr('activist')]].map(([x,n])=>'<option value="'+x+'" '+(filter===x?'selected':'')+'>'+n+'</option>').join('')+'</select>'+button(T('검색','Search'),'search')+'</div><p>'+p.length+' '+T('건','records')+' · '+(page+1)+'/'+pages+'</p><div class="grid">'+p.slice(page*24,page*24+24).map(personCard).join('')+'</div><div class="toolbar">'+button('← '+T('이전','Previous'),'prev',page===0?'disabled':'')+button(T('다음','Next')+' →','more',page>=pages-1?'disabled':'')+'</div>'}
function careerPanel(p){const f=careerFacts(p);const isFull=!p.historical&&!p.presidential&&!p.sample&&!p.governor;const stat=(label,val)=>'<div class="stat"><small>'+label+'</small><strong>'+esc(val)+'</strong></div>';return '<div class="panel"><div class="eyebrow">CAREER DOSSIER</div><h2>'+T('경력 요약','Career summary')+'</h2><div class="stats">'+stat(T('기록 수','Records'),f.recordCount)+(isFull?stat(T('기록상 재임 기간','Recorded service'),(f.days/365.2425).toFixed(1)+L('년',' yr')):'')+stat(T('첫 기록','First record'),f.first.slice(0,4))+stat(T('마지막 기록','Last record'),f.last.slice(0,4))+'</div><p>'+T('생년월일','Date of birth')+': '+esc(p.birthday||L('미등록','Unavailable'))+' · '+T('정당 이력','Party history')+': '+f.parties.map(x=>esc(tr(x))).join(' → ')+'</p><p>'+T('대표 지역','Represented states')+': '+f.states.map(stateName).map(esc).join(', ')+'</p><p>'+T('직책','Offices')+': '+f.offices.map(x=>esc(x==='election'?T('대통령 선거','Presidential election'):tr(x))).join(', ')+'</p><div class="career-timeline">'+p.terms.slice().sort((a,b)=>a.start.localeCompare(b.start)).map(t=>'<div class="career-stop"><small>'+esc(t.precision==='year'?t.start.slice(0,4):t.start)+' – '+esc(t.precision==='year'?t.end.slice(0,4):t.end)+'</small><strong>'+esc(t.type==='election'?T('대통령 선거','Presidential election'):tr(t.type))+'</strong><span>'+esc(tr(t.party||''))+' · '+esc(stateName(t.state||''))+'</span></div>').join('')+'</div><p class="muted">'+T('기록상 사실이며 능력 평가가 아닙니다. 일부 임기 및 기록은 누락될 수 있습니다.','Recorded facts, not ability ratings. Coverage may be incomplete.')+'</p>'+(p.ids?.icpsr?'<a href="https://voteview.com/person/'+encodeURIComponent(p.ids.icpsr)+'" target="_blank" rel="noopener">Voteview · ICPSR '+esc(p.ids.icpsr)+'</a>':'')+'</div>'}
function networkPanel(p){const links=observedPeers(p,people,s.year,10);const lab=k=>({state:T('동일 주','Same state'),chamber:T('동일 의회 원','Same chamber'),party:T('동일 정당','Same party')}[k]);const nodes=links.map((n,i)=>({...n,p:people.find(x=>x.id===n.id),x:Math.round(330+245*Math.cos(i*2*Math.PI/Math.max(1,links.length))),y:Math.round(182+135*Math.sin(i*2*Math.PI/Math.max(1,links.length)))}));return '<div class="panel"><h2>'+T('동시대 인물 관계망','Contemporary peer network')+' · '+s.year+'</h2><p class="muted">'+T('실제 재임기간의 겹침·같은 주·정당·의회 원으로 연결합니다. 개인적 친분이나 정치적 동맹을 뜻하지 않습니다.','Edges represent overlapping terms and shared recorded attributes, not friendship or alliances.')+'</p>'+(nodes.length?'<svg class="peer-map" viewBox="0 0 660 365" role="img" aria-label="Observed contemporaries">'+nodes.map(n=>'<line x1="330" y1="182" x2="'+n.x+'" y2="'+n.y+'" stroke="#638399" stroke-width="'+n.links.length+'"/>').join('')+'<circle cx="330" cy="182" r="27" fill="#e7c78e"/><text x="330" y="219" text-anchor="middle" fill="#eef3f7" font-size="11">'+esc(p.name.slice(0,30))+'</text>'+nodes.map(n=>'<g><circle cx="'+n.x+'" cy="'+n.y+'" r="18" fill="#426781" stroke="#a5b6c7"/><text x="'+n.x+'" y="'+(n.y+31)+'" text-anchor="middle" fill="#eef3f7" font-size="11">'+esc(n.p.name.split(' ').at(-1))+'</text></g>').join('')+'</svg><div class="peer-list">'+nodes.map(n=>'<div class="listline row"><div><strong>'+personName(n.p)+'</strong><div>'+n.links.map(k=>'<span class="tag">'+lab(k)+'</span>').join('')+'</div></div><button data-person-open="'+esc(n.id)+'">'+T('프로필','Profile')+'</button></div>').join('')+'</div>':T('이 연도에 연결 가능한 기록 없음','No matching records for this year'))+'</div>'}
function profile(){const p=people.find(x=>x.id===detail);if(!p)return peoplePage();const t=termAt(p,s.year)||p.terms.at(-1);const related=people.filter(x=>x.id!==p.id&&t.state&&termAt(x,s.year)?.state===t.state).slice(0,6);return button('← '+T('목록','List'),'closeprofile')+'<div class="panel person profile">'+photo(p,true)+'<div><h1>'+personName(p)+'</h1><p>'+esc(p.id)+' · '+esc(tr(t.party||''))+'</p><a target="_blank" rel="noopener" href="'+safeUrl(sourceLink(p))+'">'+T('원자료','Primary record')+'</a> · <a target="_blank" rel="noopener" href="'+W.sources.photos+'">'+T('의회 사진 출처','Congress photo source')+'</a> <a id="photocredit" hidden target="_blank" rel="noopener">'+T('이미지 파일 출처','Image file credit')+'</a><div class="toolbar">'+button(s.collection.includes(p.id)?T('수집 완료','Collected'):T('도감에 수집','Collect person'),'collect',s.collection.includes(p.id)?'disabled':'')+'</div></div></div>'+careerPanel(p)+networkPanel(p)+'<div class="panel"><h2>'+T('기록 및 임기','Records and terms')+'</h2>'+(p.historical?'<p class="muted">'+T('연도 단위 기록이며 실제 취임·퇴임 날짜는 원자료를 확인하세요.','Year-level records; consult sources for exact dates.')+'</p>':'')+(p.sample?'<p class="muted">'+L('기본 예시 기록: 전체 임기 및 공백은 원자료 확인.','Starter excerpt: see source for full terms and gaps.')+'</p>':'')+p.terms.map(t=>'<div class="listline">'+esc(t.start)+' – '+esc(t.end)+' · '+esc(t.type==='election'?T('선거 연도','Election year'):tr(t.type))+' · '+esc(tr(t.party||''))+' · '+esc(stateName(t.state||''))+' '+(t.district!==undefined?T('지역구','District')+' '+esc(t.district):'')+'</div>').join('')+'</div>'+(related.length?'<h2>'+T('같은 주의 동시대 의원','Contemporary legislators from the same state')+'</h2><div class="grid">'+related.map(personCard).join('')+'</div>':'')}
function governorPanel(){return '<div class="panel"><h2>'+T('역대 주지사','Historical governors')+'</h2><p>'+T('연도 단위 임기 자료 · 현직 및 일부 임기 누락 가능','Year-level term data · some incumbents or terms may be absent')+'</p><p>'+esc(govStatus)+' · '+govPeople.length+' '+T('개 기록','records')+'</p>'+button(T('주지사 자료 불러오기','Load governors'),'governors',govStatus==='loading'?'disabled':'')+' <a href="'+governorSource+'" target="_blank" rel="noopener">Scheve, White &amp; Serlin · CC BY 4.0</a><div class="grid">'+govPeople.filter(p=>termAt(p,s.year)?.state===mapState()).map(personCard).join('')+'</div><p><a href="https://www.nga.org/governors/former/" target="_blank" rel="noopener">National Governors Association</a></p></div>'}
function mapState(){return W.states.some(x=>x.id===atlasState&&x.admitted<=s.year)?atlasState:s.state}
async function autoMap(force=false){if(!s||tab!=='states')return;const state=mapState(),year=s.year,key=state+':'+congressNumber(year);if(!force&&(mapKey===key||mapAttempt===key))return;mapAttempt=key;mapBusy=true;mapData=null;mapFeature=null;mapSourceURL='';mapMessage=L('원본 지도 불러오는 중','Loading source map');render();try{const r=await districtMap(stateName(state),congressNumber(year));if(!s||mapState()!==state||congressNumber(s.year)!==congressNumber(year))return;mapData=geoPaths(r.geo);mapKey=key;mapYear=year;mapSourceURL=r.url;mapMessage=r.path}catch(e){if(mapAttempt===key)mapMessage=L('자동 지도 로딩 실패. 다시 시도하거나 원본 파일을 가져오세요.','Automatic map load failed. Retry or import the source file.')}finally{if(mapAttempt===key){mapBusy=false;if(tab==='states')render()}}}
function mapPanel(){let map='';if(mapData){map='<svg class="district-map" viewBox="0 0 800 460" role="img" aria-label="Imported district geography">'+'<g transform="translate(400 230) scale('+mapZoom+') translate(-400 -230)">'+mapData.paths.map(p=>'<path data-district="'+p.i+'" d="'+p.d+'" fill="'+(mapFeature===p.i?'#e7c78e':'#426781')+'" stroke="#b9cbd4" stroke-width=".7" tabindex="0"></path>').join('')+'</g></svg>';if(mapFeature!==null)map+='<pre class="district-info">'+esc(JSON.stringify(mapData.features[mapFeature]?.properties||{},null,2))+'</pre>'}return '<div class="panel"><h2>'+T('역사적 선거구 지도','Historical district map')+'</h2><p>'+s.year+' · '+congressNumber(s.year)+T('대 의회','th Congress')+'</p><p>'+T('선택한 주와 회기의 실제 GeoJSON을 자동으로 불러옵니다. 수동 파일은 출처를 직접 확인해야 합니다.','Automatically loads the matching state and Congress GeoJSON. Verify sources for manual imports.')+'</p><a href="'+districtSource+'" target="_blank" rel="noopener">UCLA · Lewis et al. (2013)</a><div class="toolbar">'+button(T('자동 지도 다시 불러오기','Reload source map'),'automap',mapBusy?'disabled':'')+button('−','zoomout')+button('+','zoomin')+(mapSourceURL?'<a href="'+safeUrl(mapSourceURL)+'" target="_blank" rel="noopener">'+T('원본 파일','Source file')+'</a>':'')+'</div><label>'+T('GeoJSON 파일','GeoJSON file')+'<input id="mapfile" type="file" accept=".json,.geojson,application/json"></label>'+esc(mapMessage)+(mapYear&&mapYear!==s.year?'<p class="notice">'+T('게임 연도가 변경되었습니다. 지도 파일을 다시 확인하세요.','Game year changed; verify the imported map again.')+'</p>':'')+map+'</div>'}
function statesPage(){return heading('states',T('해당 연도에 가입한 주만 표시','States admitted by the selected year'))+'<div class="states">'+W.states.filter(x=>x.admitted<=s.year).map(x=>'<button class="tile '+(mapState()===x.id?'selected':'')+'" data-state="'+x.id+'"><strong>'+x.id+'</strong><br>'+esc(x.name)+'</button>').join('')+'</div><div class="panel"><h2>'+esc(stateName(mapState()))+'</h2><p>'+T('연방 가입 연도','Admission year')+': '+W.states.find(x=>x.id===mapState()).admitted+'</p><p>'+T('이 연도 의회 인물','Congress members in this year')+'</p><div class="grid">'+activePeople().filter(x=>termAt(x,s.year)?.state===mapState()).slice(0,12).map(personCard).join('')+'</div></div>'+governorPanel()+mapPanel()}
function electionsPage(){const e=W.elections.find(x=>x.year===s.year);return heading('elections',T('실제 결과와 가상 선거를 구분','Historical results and fictional elections are separate'))+'<div class="panel"><h2>'+T('가상 선거','Fictional election')+'</h2><label>'+T('목표 직책','Target office')+'<select id="target">'+offices.filter(x=>x!=='local').map(x=>'<option value="'+x+'" '+(s.target===x?'selected':'')+'>'+tr(x)+'</option>').join('')+'</select></label><p>'+T('선출 방식','Selection method')+': '+(s.target==='sen'&&s.year<1913?T('주의회 선출','State legislature selection'):T('주민 선거','Popular election'))+'</p><p class="muted">'+L('모의 선거는 짝수 해 4분기(대통령은 4년마다)에 진행됩니다. 상원 선거 클래스·주별 주지사 일정·선거인단은 단순화되었습니다.','Fictional elections occur in Q4 of even years (every four years for president). Senate classes, governor calendars and the Electoral College are simplified.')+'</p>'+button(T('선거 상황실 열기','Open campaign war room'),'election',!career(s).retired&&eligible(s)&&s.funds>=10&&!s.elections.some(x=>x.year===s.year)?'class="primary"':'disabled')+'<p>'+s.elections.slice(-3).reverse().map(x=>x.year+' · '+tr(x.office)+' · '+tr(x.won?'won':'lost')+' ('+x.score+'/100)').join('<br>')+'</p></div><div class="panel"><h2>'+T('실제 대통령 선거','Historical presidential election')+'</h2>'+(e?'<p>'+esc(e.winner)+' · '+tr(e.party)+'<br>'+T('주요 경쟁 후보','Selected opponent')+': '+esc(e.opponent)+'</p><a target="_blank" rel="noopener" href="'+safeUrl(e.source)+'">'+T('실제 선거인단 결과','Official Electoral College results')+'</a>':L('이 연도는 대통령 선거 연도가 아닙니다.','No presidential election in this year.'))+'</div><div class="panel"><h2>'+T('선거 기록 1900–2024','Election archive 1900–2024')+'</h2>'+W.elections.map(e=>'<div class="listline"><a href="'+safeUrl(e.source)+'" target="_blank" rel="noopener">'+e.year+'</a> · '+esc(e.winner)+' · '+esc(tr(e.party))+'</div>').join('')+'</div>'}
function coalitionPanel(){if(s.mode!=='alternate'||!['rep','sen'].includes(s.office))return '';const b=coalition(s);return '<div class="panel"><h2>'+T('법안 협상 시뮬레이션','Legislative negotiation')+'</h2><p>'+T('가상 법안: 공공 인프라','Fictional bill: Public infrastructure')+'</p><p>'+T('단계','Stage')+': '+esc(b.stage)+' · '+T('가상 지지 점수','Fictional support')+': '+b.support+'/100 · '+T('타협','Concessions')+': '+b.concessions+'</p><div class="bar"><i style="width:'+b.support+'%"></i></div><div class="toolbar">'+[['hearing',T('위원회 심사','Committee hearing')],['compromise',T('수정안 타협','Amendment compromise')],['debate',T('본회의 토론','Floor debate')],['vote',T('최종 표결','Final vote')]].map(([k,v])=>button(v,'negotiate:'+k,b.result?'disabled':'')).join('')+'</div><p>'+esc(b.result||'')+'</p><p class="muted">'+T('실제 의원의 태도나 실제 의회 규칙을 예측하지 않는 추상화된 교육용 규칙입니다.','Abstract teaching rules; not actual roll calls or a prediction of lawmakers’ behavior.')+'</p></div>'}
async function loadCommittees(){committeeStatus='loading';render();try{committeeData=await currentCommittees();committeeStatus='ready'}catch(e){committeeStatus='failed'}if(tab==='congress')render()}
function committeesPanel(){const current=s.year>=2025;return '<div class="panel"><h2>'+T('위원회 명부','Committee directory')+'</h2><p>'+T('공개 자료의 현재 위원회 배정 스냅샷입니다. 과거 회기 명부가 아닙니다.','Current source snapshot only; not a historical committee roster.')+'</p>'+(current?button(T('현재 위원회 데이터','Load current committees'),'committees',committeeStatus==='loading'?'disabled':'')+' · '+esc(committeeStatus)+(committeeData?committeeData.map(c=>'<details class="listline"><summary>'+esc(c.name)+' · '+c.members.length+'</summary>'+c.members.map(m=>{const p=people.find(x=>x.id===m.id);return '<div class="row listline"><span>'+esc(p?.name||m.id)+' · '+esc(m.role)+'</span>'+(p?'<button data-person-open="'+esc(m.id)+'">'+T('프로필','Profile')+'</button>':'')+'</div>'}).join('')+'</details>').join(''):''):T('과거 위원회 배정 자료는 미연동','Historical committee assignments are not integrated'))+'<p><a href="https://github.com/unitedstates/congress-legislators" target="_blank" rel="noopener">Congress Legislators · committee data</a></p></div>'}
function billPanel(){if(s.mode!=='alternate'||!['rep','sen'].includes(s.office))return '';const l=legislature(s),b=l.bills.find(x=>x.stage!=='closed');const names={draft:T('발의','Draft'),committee:T('위원회','Committee'),calendar:T('의사일정','Calendar'),floor:T('본회의','Floor'),secondChamber:T('다른 원','Second chamber'),reconcile:T('양원 조정','Reconciliation'),executive:T('대통령 송부','Presentment'),closed:T('종료','Closed')};const actions={draft:['refer','withdraw'],committee:['hearing','markup','withdraw'],calendar:['schedule','withdraw'],floor:['amend','debate','vote','withdraw'],secondChamber:['amend','debate','vote','withdraw'],reconcile:['amend','agree','withdraw'],executive:['present','withdraw']};const label={refer:T('위원회 회부','Refer'),hearing:T('청문','Hearing'),markup:T('위원회 의결','Markup'),schedule:T('상정','Schedule'),amend:T('수정','Amend'),debate:T('토론','Debate'),vote:T('표결','Vote'),agree:T('조정안 합의','Agree'),present:T('송부 및 가상 서명','Present and fictional signature'),withdraw:T('철회','Withdraw')};return '<div class="panel"><div class="eyebrow">BICAMERAL SIMULATION</div><h2>'+T('입법 관리','Legislative management')+'</h2><p class="muted">'+T('양원과 대통령 단계의 단순화된 가상 모형입니다. 실제 필리버스터·정족수·거부권 등은 시대마다 다릅니다.','Fictional simplified bicameral model; real cloture, quorum and veto rules differ over time.')+'</p>'+(b?'<h3>'+esc(b.id)+' · '+T(agendas.find(a=>a.id===b.agenda).ko,agendas.find(a=>a.id===b.agenda).en)+'</h3><div class="stage-track">'+Object.entries(names).map(([k,v])=>'<span class="tag '+(k===b.stage?'current-stage':'')+'">'+v+'</span>').join('')+'</div><div class="stats">'+[[T('위원회','Committee'),b.committee],[T('하원','House'),b.house],[T('상원','Senate'),b.senate]].map(([k,v])=>'<div class="stat"><small>'+k+'</small><strong>'+v+'</strong><div class="bar"><i style="width:'+v+'%"></i></div></div>').join('')+'</div><div class="toolbar">'+(actions[b.stage]||[]).map(k=>button(label[k],'bill:'+b.id+':'+k)).join('')+'</div>':'<div class="toolbar">'+agendas.map(a=>button(T(a.ko,a.en),'newbill:'+a.id)).join('')+'</div>')+'<h3>'+T('입법 기록','Bill archive')+'</h3>'+l.bills.slice().reverse().map(b=>'<div class="listline">#'+b.id+' · '+esc(agendas.find(a=>a.id===b.agenda)?.en||b.agenda)+' · '+esc(b.result||b.stage)+'</div>').join('')+'</div>'}
function congress(){const list=activePeople().filter(p=>['rep','sen'].includes(termAt(p,s.year)?.type));const reps=list.filter(p=>termAt(p,s.year).type==='rep').length;const sens=list.length-reps;const bills=W.events.filter(e=>e.year===s.year);return heading('congress',T('해당 연도에 기록된 의원','Legislators recorded in this year'))+'<div class="stats"><div class="stat">'+tr('rep')+'<strong>'+reps+'</strong></div><div class="stat">'+tr('sen')+'<strong>'+sens+'</strong></div></div><p class="muted">'+L('연도 중 한 번이라도 재임한 인물의 수이며 특정 날짜의 정확한 의석 수가 아닙니다.','Counts people with terms overlapping the year, not exact seat counts at a single date.')+'</p>'+button(T('의원 데이터 불러오기','Load legislators'),'load',dataStatus==='loading'?'disabled':'')+'<div class="panel"><h2>'+T('모의 의회 활동','Fictional congressional activity')+'</h2>'+((s.mode==='alternate'&&['rep','sen'].includes(s.office))?'<p>'+L('가상 정책 의제를 선택하세요.','Select a fictional policy agenda.')+'</p>'+['Public Infrastructure','Education Funding','Budget Resolution'].map(x=>'<div class="listline">'+esc(x)+'<div class="toolbar">'+['yes','no','abstain'].map(v=>'<button data-vote="'+esc(x)+'" data-choice="'+v+'" '+(s.legislation.some(a=>a.year===s.year&&a.title===x)?'disabled':'')+'>'+tr(v)+'</button>').join('')+'</div></div>').join(''):L('대체역사 모드에서 의원으로 당선되면 가상 표결을 할 수 있습니다.','Win a congressional office in alternate history mode to cast fictional votes.'))+'</div>'+billPanel()+committeesPanel()+'<h2>'+T('동시대 의원','Contemporary members')+'</h2><div class="grid">'+list.slice(0,12).map(personCard).join('')+'</div>'}
function history(){return heading('history',T('역사적 사건과 출처','Historical events and sources'))+'<div class="panel">'+W.eras.map(e=>'<div class="listline"><strong>'+e.start+'–'+e.end+' · '+T(e.ko,e.en)+'</strong><p>'+W.events.filter(x=>x.year>=e.start&&x.year<=e.end).map(x=>'<a href="'+safeUrl(x.source)+'" target="_blank" rel="noopener">'+x.year+' · '+T(x.ko,x.en)+'</a>').join('<br>')+'</p></div>').join('')+'</div><div class="panel"><h2>'+T('도감 수집','Collection')+' · '+s.collection.length+'</h2><div class="grid">'+people.filter(p=>s.collection.includes(p.id)).slice(0,24).map(personCard).join('')+'</div></div>'}
function chooseQuiz(){const pool=activePeople().length>=4?activePeople():people;const ready=pool.filter(p=>!s.reviews.some(r=>r.id===p.id&&r.due>Date.now()));const list=ready.length?ready:pool;const p=list[Math.floor(Math.random()*list.length)];const t=termAt(p,s.year)||p.terms.at(-1);const signature=t=>[t.type,t.party,t.state,t.start.slice(0,4),t.end.slice(0,4)].join('|');let options=[p,...people.filter(x=>x.id!==p.id&&x.name!==p.name&&signature(termAt(x,s.year)||x.terms.at(-1))!==signature(t)).sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);quiz={id:p.id,term:t,options:options.map(x=>({id:x.id,name:x.name})),kind:!p.governor&&Math.random()<.5?'photo':'record'};feedback=null}
function quizPage(){if(!quiz)chooseQuiz();const p=people.find(x=>x.id===quiz.id)||basePeople().find(x=>x.id===quiz.id);const t=quiz.term;return heading('quiz',T('인출 연습과 간격 반복','Retrieval practice and spaced repetition'))+'<div class="panel"><p>'+T('복습 예정','Due now')+': '+s.reviews.filter(x=>x.due<=Date.now()).length+' · '+T('수집','Collected')+': '+s.collection.length+'</p><h2>'+T('이 인물은 누구인가요?','Who is this person?')+'</h2>'+(quiz.kind==='photo'?photo(p,false,true):'')+'<p>'+esc(tr(t.party||''))+' · '+esc(t.type==='election'?T('대통령 선거 당선자','Presidential election winner'):tr(t.type))+' · '+esc(stateName(t.state||''))+' · '+esc(t.start.slice(0,4))+'–'+esc(t.end.slice(0,4))+'</p><div class="quizchoices">'+quiz.options.map(o=>'<button data-answer="'+esc(o.id)+'" '+(feedback?'disabled':'')+'>'+esc(o.name)+'</button>').join('')+'</div>'+(feedback?'<p class="'+(feedback.correct?'correct':'wrong')+'">'+(feedback.correct?T('정답','Correct'):T('오답','Incorrect'))+' · '+personName(p)+'</p><a href="'+safeUrl(sourceLink(p))+'" target="_blank" rel="noopener">'+T('정치인 기록','Historical record')+'</a><div class="toolbar">'+button(T('다음 문제','Next question'),'quiznext','class="primary"')+'</div>':'')+'</div>'}
function settings(){return heading('settings')+'<div class="panel">'+guide.difficultySelect(difficulty(s),'settingsdifficulty')+'<p>'+T('다음 캠페인부터 적용됩니다.','Applies to the next campaign.')+'</p>'+(sessionMode==='collection'?'<label>'+T('탐색 연도','Browse year')+'<select id="collectionyear">'+Array.from({length:127},(_,i)=>1900+i).map(y=>'<option '+(y===s.year?'selected':'')+'>'+y+'</option>').join('')+'</select></label>':'')+'</div>'+'<div class="panel"><h2>'+T('게임 저장','Game save')+'</h2><p>'+T('브라우저 자동 저장 · 다른 기기에는 JSON으로 이동','Local autosave · transfer by JSON')+'</p><div class="toolbar">'+button(T('저장 파일 내보내기','Export save'),'export')+button(T('저장 파일 불러오기','Import save'),'import')+button(T('이 모드 초기화','Reset this mode'),'reset')+'</div><input id="importfile" type="file" accept=".json,application/json" hidden>'+(sessionMode==='career'?'<h2>'+T('후임 정치인','Successor')+'</h2><input id="successor" maxlength="60" placeholder="'+T('새 정치인 이름','New candidate name')+'"> '+button(T('후임 육성','Start successor'),'successor'):'')+'</div><div class="panel"><h2>'+T('자료와 한계','Sources and limitations')+'</h2><p>'+L('실제 의회 인명과 사진은 공개 데이터이며, 가상 능력치·선거·표결은 학습용입니다. 일부 사진과 한글 이름은 미등록일 수 있습니다.','Congressional names and photos are public records; fictional attributes, elections and votes are educational. Some photos and Korean names are unavailable.')+'</p>'+Object.entries(W.sources).map(([k,v])=>'<p><a target="_blank" rel="noopener" href="'+safeUrl(v)+'">'+esc(k)+'</a></p>').join('')+'</div>'}
const skillLabel={speech:['연설','Public speaking'],negotiation:['협상','Negotiation'],policy:['정책 전문성','Policy expertise'],organization:['조직 관리','Organization'],fundraising:['자금 조달','Fundraising'],networking:['정치적 관계','Networking'],media:['언론 대응','Media relations'],crisis:['위기관리','Crisis management']};
const staffLabel={manager:['선거운동 책임자','Campaign manager'],policy:['정책 보좌관','Policy aide'],press:['언론 담당자','Press aide'],fundraiser:['모금 담당자','Fundraiser']};
const campaignLabel={rally:['공개 연설','Public rally'],policy:['정책 발표','Policy announcement'],media:['언론 인터뷰','Media interview'],coalition:['연합 협상','Coalition negotiation'],donors:['후원금 모금','Donor fundraising'],crisis:['위기 대응','Crisis response'],outreach:['관계 확장','Political networking']};
function developmentPage(){const d=career(s);return heading('development',T('가상 인물만 능력치와 성장 규칙 적용','Only fictional candidates have skill ratings'))+'<div class="panel"><h2>'+esc(s.name)+' · '+T('레벨','Level')+' '+d.level+'</h2><p>XP '+d.xp+' · '+T('평판','Reputation')+' '+d.reputation+' · '+T('잔여 활동','Actions left')+' '+s.actionsLeft+(d.retired?' · '+T('은퇴','Retired'):'')+'</p><div class="skill-grid">'+skillKeys.map(k=>'<div class="skill-row"><div class="row"><strong>'+T(...skillLabel[k])+'</strong><span>'+d.skills[k]+'/100</span></div><div class="bar"><i style="width:'+d.skills[k]+'%"></i></div>'+button(T('훈련','Train'),'train:'+k,d.retired||s.actionsLeft<=0?'disabled':'')+'</div>').join('')+'</div></div><div class="panel"><h2>'+T('캠페인 팀','Campaign staff')+'</h2><p>'+T('고용 15 자금 · 분기 유지비 2 자금','Hire: 15 funds · quarterly upkeep: 2 funds')+'</p>'+staffRoles.map(k=>'<div class="row listline"><strong>'+T(...staffLabel[k])+'</strong>'+button(d.team.includes(k)?T('해고','Dismiss'):T('고용','Hire'),(d.team.includes(k)?'fire:':'hire:')+k,d.retired?'disabled':'')+'</div>').join('')+'</div><div class="panel"><h2>'+T('선거운동','Campaign')+'</h2><p>'+T('각 활동은 자금 8, 체력 12, 분기 활동 1회 소모','Each action costs 8 funds, 12 energy and one action')+'</p><div class="toolbar">'+Object.keys(campaignLabel).map(k=>button(T(...campaignLabel[k]),'campaign:'+k,d.retired||s.actionsLeft<=0?'disabled':'')).join('')+'</div>'+(d.campaign?'<p>'+T('직전 캠페인 성과','Last campaign result')+' · '+esc(d.campaign.resource||'support')+' +'+d.campaign.gain+'</p>':'')+'</div><div class="panel"><h2>'+T('정당 내 후보 경쟁','Party nomination contest')+'</h2><p>'+T('가상 예비선거: 짝수 해 1~3분기, 정당 소속, 체력 15·자금 12. 역사적 주별 경선 규칙을 재현한 것이 아닙니다.','Fictional nomination challenge in Q1–3 of even years for party members; not a reconstruction of historical state primary rules.')+'</p>'+button(T('후보 경쟁 참가','Enter nomination contest'),'primarycontest',d.retired||s.party==='Independent'||s.year%2||s.quarter>3||d.primary?.year===s.year?'disabled':'')+(d.primary?'<p>'+d.primary.year+' · '+T('가상 경선 점수','Fictional primary score')+' '+d.primary.score+' · '+(d.primary.won?T('승리','Won'):T('패배','Lost'))+'</p>':'')+'</div><div class="panel"><h2>'+T('은퇴와 세대교체','Retirement and succession')+'</h2>'+button(T('은퇴','Retire'),'retire',d.retired?'disabled':'')+'<p>'+T('후임 시작은 설정에서 가능','Start a successor in Settings')+'</p>'+d.legacy.map(x=>'<div class="listline">'+esc(x.name)+' · '+x.year+' · '+esc(tr(x.office))+' · LV '+x.level+'</div>').join('')+'</div>'}
function eventCard(e,interactive){const done=eventState(s).find(x=>x.id===e.id);return '<article class="panel"><div class="eyebrow">'+e.year+' · HISTORICAL RECORD</div><h2>'+T(e.ko,e.en)+'</h2><p>'+L(e.descriptionKo,e.descriptionEn)+'</p><a href="'+safeUrl(e.source)+'" target="_blank" rel="noopener">'+T('역사적 원자료','Historical source')+'</a><div class="event-people">'+e.people.map(id=>{const p=people.find(x=>x.id===id);return p?'<div>'+photo(p)+ '<button data-person-open="'+esc(id)+'">'+personName(p)+'</button></div>':''}).join('')+'</div>'+(interactive&&e.year===s.year?'<div class="notice">'+T('가상 커리어 대응 · 실제 역사 결과는 바뀌지 않음','Fictional career response · historical record is unchanged')+'</div>'+(done?'<p class="correct">'+T('대응 완료','Response completed')+' · '+esc(done.choice)+'</p>':'<div class="toolbar">'+[['study',T('자료 분석','Research')],['public',T('공개 입장','Public statement')],['organize',T('조직 대응','Organize')]].map(([k,v])=>button(v,'event:'+e.id+':'+k)).join('')+'</div>'):'')+'</article>'}
function eventsPage(){const now=SC.events.filter(e=>e.year===s.year);return heading('events',T('역사 기록과 가상 커리어 선택을 분리','Historical facts and fictional career choices are separate'))+'<h2>'+s.year+' · '+T('현재 이벤트','Current events')+'</h2>'+(now.length?now.map(e=>eventCard(e,true)).join(''):'<p>'+T('이번 연도에 준비된 이벤트 없음','No curated event this year')+'</p>')+'<h2>'+T('전체 역사 이벤트','Event archive')+' · '+SC.events.length+'</h2>'+SC.events.filter(e=>e.year!==s.year).map(e=>eventCard(e,false)).join('')}
function cardsPage(){const d=initCards(s,SC.events);save();const cardIds=[...new Set(SC.events.flatMap(e=>e.people))];const r=d.round,scenario=r&&!r.finished?SC.events.find(e=>e.id===r.tasks[r.step]):null;const renderCard=(id,play=false)=>{const p=people.find(x=>x.id===id);if(!p)return '';const owned=d.owned.includes(id),inDeck=d.deck.includes(id);return '<article class="political-card '+(inDeck?'in-deck':'')+'">'+photo(p)+'<strong>'+personName(p)+'</strong><small>'+p.terms.map(t=>tr(t.type)).filter((v,i,a)=>a.indexOf(v)===i).slice(0,3).join(' · ')+'</small>'+(play?button(T('카드 사용','Play card'),'playcard:'+id,r.used.includes(id)?'disabled':''):owned?button(inDeck?T('덱에서 제거','Remove from deck'):T('덱에 추가','Add to deck'),'deck:'+id,r&&!r.finished?'disabled':''):button(T('해금 · 3점','Unlock · 3 points'),'claim:'+id,s.points<3?'disabled':''))+'</article>'};return heading('cards',T('실제 역사 연결을 활용하는 싱글플레이 전략 카드','Single-player factual connection strategy cards'))+'<div class="stats"><div class="stat">'+T('보유','Owned')+'<strong>'+d.owned.length+'/'+cardIds.length+'</strong></div><div class="stat">'+T('덱','Deck')+'<strong>'+d.deck.length+'/5</strong></div><div class="stat">'+T('승리','Wins')+'<strong>'+d.wins+'</strong></div><div class="stat">'+T('패배','Losses')+'<strong>'+d.losses+'</strong></div></div><div class="panel"><h2>'+T('역사 카드 대결','History card match')+'</h2><p>'+T('덱에서 3개 역사 문제에 맞는 서로 다른 인물 카드를 사용하세요. 정답 2점, 오답은 상대 2점. 승리하면 지식 5점.','Play distinct matching people for three historical prompts. Correct +2, incorrect gives opponent +2; win earns five knowledge points.')+'</p>'+(scenario?'<h3>'+T('라운드','Round')+' '+(r.step+1)+'/3 · '+r.score+' : '+r.opponent+'</h3><p>'+L(scenario.questionKo,scenario.questionEn)+'</p><div class="card-grid">'+(r.mode==='deck'?d.deck:d.owned).map(id=>renderCard(id,true)).join('')+'</div>':(r?.finished?'<p class="'+(r.score>r.opponent?'correct':'wrong')+'">'+(r.score>r.opponent?T('승리','Victory'):T('패배','Defeat'))+' · '+r.score+' : '+r.opponent+'</p>'+r.answers.map(a=>{const e=SC.events.find(q=>q.id===a.task);const correct=e.cards.map(id=>people.find(p=>p.id===id)?.name||id).join(', ');return '<p>'+esc(L(e.questionKo,e.questionEn))+' — '+esc(correct)+' <a href="'+safeUrl(e.source)+'" target="_blank" rel="noopener">'+T('출처','Source')+'</a></p>'}).join(''):'')+button(T('덱 대결 시작','Start deck match'),'startmatch'))+'</div><div class="panel"><h2>'+T('인물 카드 컬렉션','Person card collection')+'</h2><p>'+T('기본 카드 5장 지급 · 역사 이벤트 대응과 지식 점수로 카드 해금 · 덱 최대 5장','Five starter cards · unlock via event responses or knowledge points · up to five per deck')+'</p><div class="card-grid">'+cardIds.map(id=>renderCard(id)).join('')+'</div></div>'}
