function render(){document.documentElement.lang=lang;document.documentElement.dataset.apmRelease='17.9-i1-rc';const versionLabel=document.getElementById('release-label');if(versionLabel)versionLabel.textContent='1900–PRESENT · V18 PREVIEW';$('language').textContent=lang==='ko'?'English':'한국어 + English';$('footer').textContent=T('실제 기록과 가상 시뮬레이션을 구분합니다.','Historical records and fictional simulation are distinct.')+' · V18 PREVIEW';$('sidebar').innerHTML=s?(sessionMode==='career'&&protectedMode(s)?'<div class="nav-groups">'+button(L('집무실','Office'),'v18:office','class="active"')+button(L('메인 메뉴','Main menu'),'lobby:back')+'</div>':guide.nav(s,sessionMode,tab)):'';$('app').classList.toggle('lobby-layout',!s);const screen=$('screen');if(!s){screen.innerHTML=(notice?'<div class="notice">'+esc(notice)+'</div>':'')+(sessionMode==='careerSetup'?showStart():guide.lobby());if($('lobbydifficulty'))$('lobbydifficulty').onchange=e=>{preferredDifficulty=e.target.value;localStorage.setItem('apm-difficulty',preferredDifficulty)};if($('startform')){fillStates();$('startyear').onchange=fillStates;const updateMode=()=>{const m=$('careermode').value;$('startstate').disabled=m==='state51';$('v18-mode-hint').textContent=m==='staff'?L('가상 추가 참모로 성장합니다. 실제 선거와 공직자는 변경되지 않습니다.','Grow as a fictional additional aide. Historical election outcomes and officeholders remain fixed.'):m==='state51'?L('가상의 주에서 지방·주정부 직책에 도전합니다. 실제 연방 역사와 분리됩니다.','Run for fictional local and state offices, separate from federal history.'):L('가상 선거와 정치적 결과를 자유롭게 바꿀 수 있습니다.','Simulate alternative elections and political outcomes.')};$('careermode').onchange=updateMode;updateMode();$('startform').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);careerSlot=freeCareer(localStorage,f.get('mode'));if(!careerSlot){notice=T('빈 저장 슬롯이 없습니다.','No free save slot.');render();return}const fresh=newGame(f.get('name').trim()||'Alex Morgan',f.get('mode')==='state51'?'X51':f.get('state'),f.get('party'),+f.get('year'),f.get('mode'));if(protectedMode(fresh)){career18(fresh);calendar18(fresh)}fresh.difficulty=difficulties[f.get('difficulty')]?f.get('difficulty'):preferredDifficulty;fresh.actionsLeft=2;try{if(!saveCareer(localStorage,careerSlot,fresh))throw Error('Invalid career')}catch{notice=T('새 커리어를 저장할 수 없습니다. 기존 저장은 유지됩니다.','Could not save the new career. Existing saves are preserved.');render();return}sessionMode='career';s=fresh;tab='home';save();render();if(dataStatus==='seed')loadPeople()}}return}if(sessionMode==='career'&&protectedMode(s)){if(!newsLoadError)ingestNews(calendar18(s),news18,calendar18(s).date);screen.innerHTML=(notice?'<div class="notice">'+esc(notice)+'</div>':'')+renderCareer18(s,{L,esc,button,world:W,people:activePeople(),photo,sourceLink,news:news18,catalog:calendarCatalog,catalogLoading:calendarLoading||newsLoadError,newsLoadError});hydratePhotos();return}const views={home:()=>home()+encounters.journal(),warroom:()=>electionHeader18(s,{L,esc})+v17.warroom(),inbox:v17.inbox,relations:()=>encounters.render('relations')+v17.relations()+encounters.journal(),party:()=>encounters.render('party')+v17.party(),challenges:v17.challenges,development:developmentPage,events:eventsPage,cards:cardsPage,people:()=>detail?profile():peoplePage(),states:statesPage,elections:electionsPage,congress:()=>encounters.render('congress')+congress(),history,quiz:quizPage,settings};if(!unlocked(s,tab,sessionMode))tab=sessionMode==='career'?'home':sessionMode==='collection'?'people':sessionMode==='tutorial'?'warroom':'challenges';screen.innerHTML=(notice?'<div class="notice">'+esc(notice)+'</div>':'')+views[tab]();if($('settingsdifficulty')){$('settingsdifficulty').disabled=v17.active()||sessionMode==='tutorial';$('settingsdifficulty').onchange=e=>{s.difficulty=e.target.value;save();render()}}if($('collectionyear'))$('collectionyear').onchange=e=>{s.year=+e.target.value;quiz=null;feedback=null;atlasState=null;mapData=null;mapKey='';mapAttempt='';save();render()};if(tab==='people'&&$('search'))$('search').onkeydown=e=>{if(e.key==='Enter'){query=e.target.value;page=0;render()}};if($('scope'))$('scope').onchange=e=>{scope=e.target.value;page=0;render()};if($('filter'))$('filter').onchange=e=>{filter=e.target.value;page=0;render()};if($('target')){$('target').disabled=v17.active();$('target').onchange=e=>{if(!v17.active())s.target=e.target.value;save();render()}};if($('mapfile'))$('mapfile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>40000000)throw Error('Too large');mapData=geoPaths(JSON.parse(await f.text()));mapFeature=null;mapYear=s.year;mapMessage=f.name;mapSourceURL='';mapKey='manual';mapZoom=1}catch(err){mapMessage=L('파일을 읽지 못했습니다.','Could not read file.');mapData=null}render()};if($('importfile'))$('importfile').onchange=async e=>{try{if(v17.active())throw Error('Campaign in progress');const v=JSON.parse(await e.target.files[0].text());if(protectedMode(v)||v.schema!==1||!W.states.some(x=>x.id===v.state)||!Number.isInteger(v.year)||v.year<1900||v.year>2026||!['reviews','collection','history','legislation','elections'].every(k=>Array.isArray(v[k])))throw Error('Invalid');s=v;migrateCollection();resetView();tab=sessionMode==='career'?'home':sessionMode==='collection'?'people':sessionMode==='tutorial'?'warroom':'challenges';save();render()}catch(err){notice=L('잘못된 저장 파일','Invalid save file');render()}};hydratePhotos()}
